1	// ---------------------------------------------------------------------------
2	// Analytics Aggregation — server-side helpers for the analytics dashboard
3	// All queries are scoped by `shop` (security requirement)
4	// ---------------------------------------------------------------------------
5	
6	import db from "../db.server";
7	
8	// ---------------------------------------------------------------------------
9	// Types
10	// ---------------------------------------------------------------------------
11	
12	export interface DateRange {
13	  from: Date;
14	  to: Date;
15	}
16	
17	export interface AnalyticsSummary {
18	  totalViews: number;
19	  totalClicks: number;
20	  totalRecommendations: number;
21	  totalConversions: number;
22	  totalDismissals: number;
23	}
24	
25	export interface ConversionFunnel {
26	  viewCount: number;
27	  clickRate: number; // clicks / views (0–1)
28	  recommendRate: number; // recommends / views (0–1)
29	  convertRate: number; // converts / views (0–1)
30	}
31	
32	export interface ChartPerformance {
33	  sizeChartId: string;
34	  name: string;
35	  views: number;
36	  clicks: number;
37	  recommendations: number;
38	  conversions: number;
39	}
40	
41	export interface DailyDataPoint {
42	  date: string; // ISO date string "YYYY-MM-DD"
43	  count: number;
44	}
45	
46	export interface ProductPerformance {
47	  productId: string;
48	  views: number;
49	  clicks: number;
50	  recommendations: number;
51	  conversions: number;
52	}
53	
54	// ---------------------------------------------------------------------------
55	// getAnalyticsSummary
56	// Returns totals for each event type within the given date range.
57	// ---------------------------------------------------------------------------
58	
59	export async function getAnalyticsSummary(
60	  shop: string,
61	  dateRange: DateRange,
62	): Promise<AnalyticsSummary> {
63	  const where = {
64	    shop,
65	    createdAt: { gte: dateRange.from, lte: dateRange.to },
66	  };
67	
68	  const [views, clicks, recommendations, conversions, dismissals] =
69	    await Promise.all([
70	      db.analyticsEvent.count({ where: { ...where, eventType: "view" } }),
71	      db.analyticsEvent.count({ where: { ...where, eventType: "click" } }),
72	      db.analyticsEvent.count({ where: { ...where, eventType: "recommend" } }),
73	      db.analyticsEvent.count({ where: { ...where, eventType: "convert" } }),
74	      db.analyticsEvent.count({ where: { ...where, eventType: "dismiss" } }),
75	    ]);
76	
77	  return {
78	    totalViews: views,
79	    totalClicks: clicks,
80	    totalRecommendations: recommendations,
81	    totalConversions: conversions,
82	    totalDismissals: dismissals,
83	  };
84	}
85	
86	// ---------------------------------------------------------------------------
87	// getConversionFunnel
88	// Returns step-level rates so the UI can render a funnel chart.
89	// ---------------------------------------------------------------------------
90	
91	export async function getConversionFunnel(
92	  shop: string,
93	  dateRange: DateRange,
94	): Promise<ConversionFunnel> {
95	  const summary = await getAnalyticsSummary(shop, dateRange);
96	
97	  const safe = (numerator: number, denominator: number): number => {
98	    if (denominator === 0) return 0;
99	    return Math.round((numerator / denominator) * 10000) / 10000; // 4 dp
100	  };
101	
102	  return {
103	    viewCount: summary.totalViews,
104	    clickRate: safe(summary.totalClicks, summary.totalViews),
105	    recommendRate: safe(summary.totalRecommendations, summary.totalViews),
106	    convertRate: safe(summary.totalConversions, summary.totalViews),
107	  };
108	}
109	
110	// ---------------------------------------------------------------------------
111	// getTopCharts
112	// Returns top N size charts ordered by view count within the date range.
113	// Joins with the SizeChart table to include chart names.
114	// ---------------------------------------------------------------------------
115	
116	export async function getTopCharts(
117	  shop: string,
118	  dateRange: DateRange,
119	  limit: number = 10,
120	): Promise<ChartPerformance[]> {
121	  // Aggregate view events grouped by sizeChartId
122	  const eventTypes: ("view" | "click" | "recommend" | "convert")[] = [
123	    "view",
124	    "click",
125	    "recommend",
126	    "convert",
127	  ];
128	
129	  const where = {
130	    shop,
131	    sizeChartId: { not: null },
132	    createdAt: { gte: dateRange.from, lte: dateRange.to },
133	  };
134	
135	  // Run all four aggregations in parallel
136	  const [viewGroups, clickGroups, recommendGroups, convertGroups] =
137	    await Promise.all(
138	      eventTypes.map((eventType) =>
139	        db.analyticsEvent.groupBy({
140	          by: ["sizeChartId"],
141	          where: { ...where, eventType },
142	          _count: { id: true },
143	          orderBy: { _count: { id: "desc" } },
144	        }),
145	      ),
146	    );
147	
148	  // Build a lookup map: sizeChartId → { views, clicks, recommends, converts }
149	  type CountMap = Map<string, number>;
150	
151	  const toMap = (
152	    groups: { sizeChartId: string | null; _count: { id: number } }[],
153	  ): CountMap => {
154	    const m: CountMap = new Map();
155	    for (const g of groups) {
156	      if (g.sizeChartId) m.set(g.sizeChartId, g._count.id);
157	    }
158	    return m;
159	  };
160	
161	  const viewMap = toMap(viewGroups);
162	  const clickMap = toMap(clickGroups);
163	  const recommendMap = toMap(recommendGroups);
164	  const convertMap = toMap(convertGroups);
165	
166	  // Collect all chart IDs that have at least one view
167	  const topIds = [...viewMap.entries()]
168	    .sort((a, b) => b[1] - a[1])
169	    .slice(0, limit)
170	    .map(([id]) => id);
171	
172	  if (topIds.length === 0) return [];
173	
174	  // Fetch chart names from the DB in a single query
175	  const charts = await db.sizeChart.findMany({
176	    where: { shop, id: { in: topIds } },
177	    select: { id: true, name: true },
178	  });
179	
180	  const nameMap = new Map<string, string>(charts.map((c) => [c.id, c.name]));
181	
182	  return topIds.map((id) => ({
183	    sizeChartId: id,
184	    name: nameMap.get(id) ?? "Deleted chart",
185	    views: viewMap.get(id) ?? 0,
186	    clicks: clickMap.get(id) ?? 0,
187	    recommendations: recommendMap.get(id) ?? 0,
188	    conversions: convertMap.get(id) ?? 0,
189	  }));
190	}
191	
192	// ---------------------------------------------------------------------------
193	// getDailyTrend
194	// Returns daily event counts for the given event type across the date range.
195	// Used for time-series charts in the analytics dashboard.
196	// ---------------------------------------------------------------------------
197	
198	export async function getDailyTrend(
199	  shop: string,
200	  dateRange: DateRange,
201	  eventType: string,
202	): Promise<DailyDataPoint[]> {
203	  const events = await db.analyticsEvent.findMany({
204	    where: {
205	      shop,
206	      eventType,
207	      createdAt: { gte: dateRange.from, lte: dateRange.to },
208	    },
209	    select: { createdAt: true },
210	    orderBy: { createdAt: "asc" },
211	  });
212	
213	  // Aggregate counts by calendar date (YYYY-MM-DD)
214	  const countByDate = new Map<string, number>();
215	
216	  for (const event of events) {
217	    const dateKey = event.createdAt.toISOString().slice(0, 10);
218	    countByDate.set(dateKey, (countByDate.get(dateKey) ?? 0) + 1);
219	  }
220	
221	  // Fill in zero-count dates across the full range so charts render correctly
222	  const result: DailyDataPoint[] = [];
223	  const cursor = new Date(dateRange.from);
224	  cursor.setUTCHours(0, 0, 0, 0);
225	  const end = new Date(dateRange.to);
226	  end.setUTCHours(23, 59, 59, 999);
227	
228	  while (cursor <= end) {
229	    const dateKey = cursor.toISOString().slice(0, 10);
230	    result.push({ date: dateKey, count: countByDate.get(dateKey) ?? 0 });
231	    cursor.setUTCDate(cursor.getUTCDate() + 1);
232	  }
233	
234	  return result;
235	}
236	
237	// ---------------------------------------------------------------------------
238	// getProductPerformance
239	// Returns per-product event counts, scoped to a shop and date range.
240	// Useful for identifying which products benefit most from size charts.
241	// ---------------------------------------------------------------------------
242	
243	export async function getProductPerformance(
244	  shop: string,
245	  dateRange: DateRange,
246	): Promise<ProductPerformance[]> {
247	  const where = {
248	    shop,
249	    productId: { not: null },
250	    createdAt: { gte: dateRange.from, lte: dateRange.to },
251	  };
252	
253	  const eventTypes: string[] = ["view", "click", "recommend", "convert"];
254	
255	  const groups = await Promise.all(
256	    eventTypes.map((eventType) =>
257	      db.analyticsEvent.groupBy({
258	        by: ["productId"],
259	        where: { ...where, eventType },
260	        _count: { id: true },
261	      }),
262	    ),
263	  );
264	
265	  const [viewGroups, clickGroups, recommendGroups, convertGroups] = groups;
266	
267	  type ProductMap = Map<string, number>;
268	
269	  const toProductMap = (
270	    g: { productId: string | null; _count: { id: number } }[],
271	  ): ProductMap => {
272	    const m: ProductMap = new Map();
273	    for (const row of g) {
274	      if (row.productId) m.set(row.productId, row._count.id);
275	    }
276	    return m;
277	  };
278	
279	  const viewMap = toProductMap(viewGroups);
280	  const clickMap = toProductMap(clickGroups);
281	  const recommendMap = toProductMap(recommendGroups);
282	  const convertMap = toProductMap(convertGroups);
283	
284	  // Union of all product IDs across event types
285	  const allProductIds = new Set<string>([
286	    ...viewMap.keys(),
287	    ...clickMap.keys(),
288	    ...recommendMap.keys(),
289	    ...convertMap.keys(),
290	  ]);
291	
292	  return [...allProductIds]
293	    .map((productId) => ({
294	      productId,
295	      views: viewMap.get(productId) ?? 0,
296	      clicks: clickMap.get(productId) ?? 0,
297	      recommendations: recommendMap.get(productId) ?? 0,
298	      conversions: convertMap.get(productId) ?? 0,
299	    }))
300	    .sort((a, b) => b.views - a.views);
301	}
302	
303	// ---------------------------------------------------------------------------
304	// buildDateRange
305	// Convenience helper: builds a DateRange from a preset string.
306	// Consumers can use this instead of constructing Date objects manually.
307	// ---------------------------------------------------------------------------
308	
309	export function buildDateRange(
310	  preset: "7d" | "30d" | "90d" | "365d",
311	): DateRange {
312	  const to = new Date();
313	  const from = new Date();
314	
315	  const days: Record<typeof preset, number> = {
316	    "7d": 7,
317	    "30d": 30,
318	    "90d": 90,
319	    "365d": 365,
320	  };
321	
322	  from.setDate(from.getDate() - days[preset]);
323	  from.setHours(0, 0, 0, 0);
324	
325	  return { from, to };
326	}
