263	// ---------------------------------------------------------------------------
264	// getActiveSubscription
265	// Fetches the merchant's current active subscription from Shopify.
266	// Returns null when on the free plan (no active charge).
267	// ---------------------------------------------------------------------------
268	
269	export async function getActiveSubscription(
270	  context: BillingContext,
271	): Promise<ActiveShopifySubscription | null> {
272	  const response = await context.admin.graphql(CURRENT_APP_INSTALLATION_QUERY);
273	  const body = (await response.json()) as CurrentAppInstallationResponse;
274	
275	  const subs =
276	    body.data.currentAppInstallation.activeSubscriptions;
277	
278	  if (!subs || subs.length === 0) return null;
279	
280	  // Prefer ACTIVE status; fall back to first entry
281	  const active =
282	    subs.find((s) => s.status === "ACTIVE") ?? subs[0];
283	
284	  return {
285	    id: active.id,
286	    name: active.name,
287	    status: active.status,
288	    createdAt: active.createdAt,
289	    currentPeriodEnd: active.currentPeriodEnd,
290	    test: active.test,
291	  };
292	}
