1	// ---------------------------------------------------------------------------
2	// AI Recommendation Engine — statistical anthropometric model
3	// Based on CDC/WHO body proportion data
4	// ---------------------------------------------------------------------------
5	
6	export interface RecommendInput {
7	  height: number; // cm
8	  weight: number; // kg
9	  gender: "male" | "female";
10	  bodyType: "slim" | "regular" | "athletic" | "plus";
11	  chartData: { headers: string[]; rows: Record<string, string>[] };
12	}
13	
14	export interface RecommendResult {
15	  recommendedSize: string;
16	  confidence: number; // 0–100
17	  alternatives: { size: string; confidence: number }[];
18	  estimatedMeasurements: Record<string, number>;
19	}
20	
21	// ---------------------------------------------------------------------------
22	// Anthropometric proportion tables (CDC/WHO-based)
23	// Values represent the coefficient of height used to estimate each measurement
24	// at a reference BMI of 22. Actual values are adjusted by BMI and body type.
25	// ---------------------------------------------------------------------------
26	
27	interface ProportionTable {
28	  chestBase: number; // chest / height at BMI 22
29	  waistBase: number; // waist / height at BMI 22
30	  hipsBase: number; // hips / height at BMI 22
31	  shoulderBase: number; // shoulder width / height at BMI 22
32	  armLengthBase: number; // arm length / height at BMI 22
33	  inseamBase: number; // inseam / height at BMI 22
34	  bmiFactor: number; // cm added per BMI unit above/below 22
35	}
36	
37	const PROPORTIONS: Record<"male" | "female", ProportionTable> = {
38	  male: {
39	    chestBase: 0.530,
40	    waistBase: 0.435,
41	    hipsBase: 0.510,
42	    shoulderBase: 0.245,
43	    armLengthBase: 0.330,
44	    inseamBase: 0.455,
45	    bmiFactor: 0.85,
46	  },
47	  female: {
48	    chestBase: 0.510,
49	    waistBase: 0.390,
50	    hipsBase: 0.540,
51	    shoulderBase: 0.225,
52	    armLengthBase: 0.305,
53	    inseamBase: 0.445,
54	    bmiFactor: 0.75,
55	  },
56	};
57	
58	// ---------------------------------------------------------------------------
59	// Body-type adjustment multipliers applied to estimated measurements
60	// ---------------------------------------------------------------------------
61	
62	interface BodyTypeAdjustment {
63	  chest: number;
64	  waist: number;
65	  hips: number;
66	  shoulder: number;
67	}
68	
69	const BODY_TYPE_ADJUSTMENTS: Record<
70	  "slim" | "regular" | "athletic" | "plus",
71	  BodyTypeAdjustment
72	> = {
73	  slim: { chest: -0.05, waist: -0.05, hips: -0.04, shoulder: -0.02 },
74	  regular: { chest: 0, waist: 0, hips: 0, shoulder: 0 },
75	  athletic: { chest: 0.05, waist: -0.05, hips: -0.02, shoulder: 0.04 },
76	  plus: { chest: 0.08, waist: 0.10, hips: 0.10, shoulder: 0.04 },
77	};
78	
79	// ---------------------------------------------------------------------------
80	// Canonical measurement column name patterns
81	// Used to map chart headers to measurement types
82	// ---------------------------------------------------------------------------
83	
84	const MEASUREMENT_PATTERNS: Record<string, RegExp> = {
85	  chest: /chest|bust|torso/i,
86	  waist: /waist/i,
87	  hips: /hip/i,
88	  shoulder: /shoulder/i,
89	  armLength: /arm.?length|sleeve/i,
90	  inseam: /inseam|inside.?leg/i,
91	  height: /height|stature/i,
92	};
93	
94	// ---------------------------------------------------------------------------
95	// Estimate body measurements from height, weight, gender, body type
96	// ---------------------------------------------------------------------------
97	
98	export function estimateMeasurements(
99	  height: number,
100	  weight: number,
101	  gender: "male" | "female",
102	  bodyType: "slim" | "regular" | "athletic" | "plus",
103	): Record<string, number> {
104	  const p = PROPORTIONS[gender];
105	  const adj = BODY_TYPE_ADJUSTMENTS[bodyType];
106	
107	  const bmi = weight / ((height / 100) ** 2);
108	  const bmiDelta = bmi - 22;
109	
110	  const chest =
111	    height * p.chestBase + bmiDelta * p.bmiFactor * (1 + adj.chest);
112	  const waist =
113	    height * p.waistBase + bmiDelta * p.bmiFactor * (1 + adj.waist);
114	  const hips =
115	    height * p.hipsBase + bmiDelta * p.bmiFactor * (1 + adj.hips);
116	  const shoulder =
117	    height * p.shoulderBase * (1 + adj.shoulder);
118	  const armLength = height * p.armLengthBase;
119	  const inseam = height * p.inseamBase;
120	
121	  return {
122	    chest: Math.round(chest * 10) / 10,
123	    waist: Math.round(waist * 10) / 10,
124	    hips: Math.round(hips * 10) / 10,
125	    shoulder: Math.round(shoulder * 10) / 10,
126	    armLength: Math.round(armLength * 10) / 10,
127	    inseam: Math.round(inseam * 10) / 10,
128	    height,
129	  };
130	}
131	
132	// ---------------------------------------------------------------------------
133	// Parse a measurement value from a chart cell.
134	// Handles plain numbers ("34"), ranges ("32-34"), values with units ("34 cm"),
135	// and fractional values ("34.5").
136	// Returns the numeric midpoint in cm (or the plain value if no range).
137	// ---------------------------------------------------------------------------
138	
139	function parseMeasurementValue(raw: string): number | null {
140	  if (!raw || raw.trim() === "" || raw.trim() === "-") return null;
141	
142	  // Strip units and extra whitespace
143	  const cleaned = raw.replace(/\s*(cm|in|inches?|")\s*/gi, "").trim();
144	
145	  // Range pattern: "32-34" or "32–34" (en-dash)
146	  const rangeMatch = cleaned.match(/^(\d+(?:\.\d+)?)\s*[-–]\s*(\d+(?:\.\d+)?)$/);
147	  if (rangeMatch) {
148	    const lo = parseFloat(rangeMatch[1]);
149	    const hi = parseFloat(rangeMatch[2]);
150	    return (lo + hi) / 2;
151	  }
152	
153	  // Plain number
154	  const num = parseFloat(cleaned);
155	  return isNaN(num) ? null : num;
156	}
157	
158	// ---------------------------------------------------------------------------
159	// Identify the size label column (the column that holds "S", "M", "L", etc.)
160	// Returns the header key most likely to be the size label, or the first key.
161	// ---------------------------------------------------------------------------
162	
163	function findSizeColumnKey(headers: string[]): string {
164	  const sizePattern = /^size$/i;
165	  const found = headers.find((h) => sizePattern.test(h.trim()));
166	  return found ?? headers[0];
167	}
168	
169	// ---------------------------------------------------------------------------
170	// Map a chart header to a canonical measurement type key.
171	// Returns null if no match found.
172	// ---------------------------------------------------------------------------
173	
174	function headerToMeasurementKey(header: string): string | null {
175	  for (const [key, pattern] of Object.entries(MEASUREMENT_PATTERNS)) {
176	    if (pattern.test(header)) return key;
177	  }
178	  return null;
179	}
180	
181	// ---------------------------------------------------------------------------
182	// Compute Euclidean distance between estimated measurements and a chart row.
183	// Only the measurements present in both sets are compared.
184	// Returns { distance, matchedFields } where matchedFields is how many
185	// measurement columns contributed to the score.
186	// ---------------------------------------------------------------------------
187	
188	function scoreRow(
189	  estimated: Record<string, number>,
190	  row: Record<string, string>,
191	  headers: string[],
192	): { distance: number; matchedFields: number } {
193	  let sumSquares = 0;
194	  let matchedFields = 0;
195	
196	  for (const header of headers) {
197	    const measurementKey = headerToMeasurementKey(header);
198	    if (!measurementKey) continue;
199	
200	    const estimatedValue = estimated[measurementKey];
201	    if (estimatedValue === undefined) continue;
202	
203	    const rawCell = row[header];
204	    if (!rawCell) continue;
205	
206	    const chartValue = parseMeasurementValue(rawCell);
207	    if (chartValue === null) continue;
208	
209	    const diff = estimatedValue - chartValue;
210	    sumSquares += diff * diff;
211	    matchedFields++;
212	  }
213	
214	  if (matchedFields === 0) return { distance: Infinity, matchedFields: 0 };
215	  return { distance: Math.sqrt(sumSquares / matchedFields), matchedFields };
216	}
217	
218	// ---------------------------------------------------------------------------
219	// Convert a distance (cm) to a 0–100 confidence score.
220	// Distance of 0 → 100, distance of 10 cm → ~50, distance >= 20 → near 0.
221	// Uses an exponential decay: confidence = 100 * exp(-distance / 7)
222	// ---------------------------------------------------------------------------
223	
224	function distanceToConfidence(distance: number): number {
225	  if (!isFinite(distance)) return 0;
226	  const raw = 100 * Math.exp(-distance / 7);
227	  return Math.round(Math.min(100, Math.max(0, raw)));
228	}
229	
230	// ---------------------------------------------------------------------------
231	// Main recommendation function
232	// ---------------------------------------------------------------------------
233	
234	export function recommendSize(input: RecommendInput): RecommendResult {
235	  const { height, weight, gender, bodyType, chartData } = input;
236	
237	  const estimated = estimateMeasurements(height, weight, gender, bodyType);
238	  const { headers, rows } = chartData;
239	
240	  if (!headers.length || !rows.length) {
241	    return {
242	      recommendedSize: "",
243	      confidence: 0,
244	      alternatives: [],
245	      estimatedMeasurements: estimated,
246	    };
247	  }
248	
249	  const sizeKey = findSizeColumnKey(headers);
250	
251	  // Score every row
252	  const scored = rows
253	    .map((row) => {
254	      const sizeLabel = (row[sizeKey] ?? "").trim();
255	      if (!sizeLabel) return null;
256	
257	      const { distance, matchedFields } = scoreRow(estimated, row, headers);
258	
259	      // Penalise rows with too few matching measurement fields
260	      const adjustedDistance =
261	        matchedFields === 0 ? Infinity : distance * (1 + 0.1 / matchedFields);
262	
263	      return { size: sizeLabel, distance: adjustedDistance, matchedFields };
264	    })
265	    .filter(
266	      (
267	        r,
268	      ): r is { size: string; distance: number; matchedFields: number } =>
269	        r !== null && isFinite(r.distance),
270	    )
271	    .sort((a, b) => a.distance - b.distance);
272	
273	  if (!scored.length) {
274	    return {
275	      recommendedSize: "",
276	      confidence: 0,
277	      alternatives: [],
278	      estimatedMeasurements: estimated,
279	    };
280	  }
281	
282	  const best = scored[0];
283	  const alternatives = scored
284	    .slice(1, 4)
285	    .map((r) => ({
286	      size: r.size,
287	      confidence: distanceToConfidence(r.distance),
288	    }))
289	    .filter((r) => r.confidence > 5);
290	
291	  return {
292	    recommendedSize: best.size,
293	    confidence: distanceToConfidence(best.distance),
294	    alternatives,
295	    estimatedMeasurements: estimated,
296	  };
297	}
