1	import { useState } from "react";
2	
3	interface BarChartDataPoint {
4	  label: string;
5	  value: number;
6	}
7	
8	interface BarChartProps {
9	  data: BarChartDataPoint[];
10	  height?: number;
11	  barColor?: string;
12	  showLabels?: boolean;
13	}
14	
15	const GRID_LINES = [0.25, 0.5, 0.75, 1];
16	const LABEL_AREA_HEIGHT = 36;
17	const Y_AXIS_WIDTH = 40;
18	const BAR_GAP_RATIO = 0.3; // 30% of available slot is gap
19	
20	export function BarChart({
21	  data,
22	  height = 200,
23	  barColor = "#2c6ecb",
24	  showLabels = true,
25	}: BarChartProps) {
26	  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
27	
28	  if (data.length === 0) {
29	    return (
30	      <svg
31	        width="100%"
32	        height={height + (showLabels ? LABEL_AREA_HEIGHT : 0)}
33	        aria-label="Bar chart — no data"
34	      />
35	    );
36	  }
37	
38	  const maxValue = Math.max(...data.map((d) => d.value), 1);
39	  const chartHeight = height;
40	  const totalHeight = chartHeight + (showLabels ? LABEL_AREA_HEIGHT : 0);
41	
42	  return (
43	    <svg
44	      width="100%"
45	      viewBox={`0 0 ${400 + Y_AXIS_WIDTH} ${totalHeight}`}
46	      preserveAspectRatio="none"
47	      style={{ display: "block", width: "100%" }}
48	      aria-label="Bar chart"
49	    >
50	      {/* Grid lines */}
51	      {GRID_LINES.map((fraction) => {
52	        const y = chartHeight - fraction * chartHeight;
53	        const gridValue = Math.round(maxValue * fraction);
54	        return (
55	          <g key={fraction}>
56	            <line
57	              x1={Y_AXIS_WIDTH}
58	              y1={y}
59	              x2={400 + Y_AXIS_WIDTH}
60	              y2={y}
61	              stroke="#e3e3e3"
62	              strokeWidth={1}
63	            />
64	            <text
65	              x={Y_AXIS_WIDTH - 4}
66	              y={y + 4}
67	              textAnchor="end"
68	              fontSize={10}
69	              fill="#8c9196"
70	            >
71	              {gridValue.toLocaleString()}
72	            </text>
73	          </g>
74	        );
75	      })}
76	
77	      {/* Bars */}
78	      {data.map((point, i) => {
79	        const slotWidth = 400 / data.length;
80	        const barWidth = slotWidth * (1 - BAR_GAP_RATIO);
81	        const x = Y_AXIS_WIDTH + i * slotWidth + (slotWidth - barWidth) / 2;
82	        const barHeight = (point.value / maxValue) * chartHeight;
83	        const y = chartHeight - barHeight;
84	        const isHovered = hoveredIndex === i;
85	
86	        return (
87	          <g key={i}>
88	            <rect
89	              x={x}
90	              y={y}
91	              width={barWidth}
92	              height={barHeight}
93	              fill={isHovered ? "#1a4f9b" : barColor}
94	              rx={2}
95	              onMouseEnter={() => setHoveredIndex(i)}
96	              onMouseLeave={() => setHoveredIndex(null)}
97	              style={{ cursor: "default", transition: "fill 0.1s ease" }}
98	            />
99	
100	            {/* Tooltip on hover */}
101	            {isHovered && (
102	              <g>
103	                <rect
104	                  x={x + barWidth / 2 - 28}
105	                  y={Math.max(y - 28, 2)}
106	                  width={56}
107	                  height={20}
108	                  rx={3}
109	                  fill="#202223"
110	                />
111	                <text
112	                  x={x + barWidth / 2}
113	                  y={Math.max(y - 13, 17)}
114	                  textAnchor="middle"
115	                  fontSize={10}
116	                  fill="#ffffff"
117	                >
118	                  {point.value.toLocaleString()}
119	                </text>
120	              </g>
