48	  if (request.method === "OPTIONS") {
49	    return corsOptions();
50	  }
51	
52	  if (request.method !== "POST") {
53	    return corsJson({ error: "Method not allowed" }, { status: 405 });
54	  }
55	
56	  let body: Partial<AnalyticsEventBody>;
57	
58	  try {
59	    body = (await request.json()) as Partial<AnalyticsEventBody>;
60	  } catch {
61	    return corsJson({ error: "Invalid JSON body" }, { status: 400 });
62	  }
63	
64	  const { shop, eventType, sizeChartId, productId, metadata } = body;
65	
66	  // Validate shop
67	  const shopError = validateShop(shop ?? null);
68	  if (shopError) return shopError;
