interface DisplaySettings {
  priority: number;
  countries: "all" | "selected";
  selectedCountries: string;
  buttonPosition: "floating" | "above_desc" | "below_desc";
}

interface ChartData {
  headers: string[];
  units: { default: string; available: string[] };
  rows: Record<string, string>[];
  displaySettings?: DisplaySettings;
  recommendationEnabled?: boolean;
}

interface Assignment {
  id: string;
  assignmentType: string;
  assignmentValue: string;
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request, params }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const id = params.id;

  if (!id) throw new Response("Not found", { status: 404 });

  if (id === "new") {
    return {
      chart: null as null,
      assignments: [] as Assignment[],
      isNew: true,
    };
  }

  const chart = await db.sizeChart.findFirst({
    where: { id, shop },
    include: { assignments: true },
  });

  if (!chart) {
    throw new Response("Not found", { status: 404 });
  }

  return {
    chart: {
      id: chart.id,
      name: chart.name,
      category: chart.category,
      status: chart.status,
      data: chart.data,
      createdAt: chart.createdAt.toISOString(),
      updatedAt: chart.updatedAt.toISOString(),
    },
    assignments: chart.assignments.map((a) => ({
      id: a.id,
      assignmentType: a.assignmentType,
      assignmentValue: a.assignmentValue,
    })),
    isNew: false,
  };
};

// ---------------------------------------------------------------------------
// Action
// ---------------------------------------------------------------------------

export const action = async ({ request, params }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const id = params.id;
  if (!id) return { error: "Missing chart ID" };
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    switch (intent) {
      case "save": {
        const name = formData.get("name") as string;
        const category = formData.get("category") as string;
        const status = formData.get("status") as string;
        const dataRaw = formData.get("data") as string;

        if (!name?.trim()) return { error: "Chart name is required" };

        let parsedData: ChartData;
        try {
          parsedData = JSON.parse(dataRaw) as ChartData;
        } catch {
          return { error: "Invalid chart data. Please try again." };
        }

        if (id === "new") {
          const chart = await db.sizeChart.create({
            data: {
              shop,
              name: name.trim(),
              category,
              status,
              data: JSON.stringify(parsedData),
            },
          });
          return redirect(`/app/size-charts/${chart.id}?saved=1`);
        }

        const existing = await db.sizeChart.findFirst({ where: { id, shop } });
